@namespace Components

<div class="checkout-wizard">
    @if (_step == Step.Shipping)
    {
        <ShippingStep Shipping="@_order.Shipping"
                      OnNext="@HandleShippingComplete" />
    }
    else
    {
        <PaymentStep Payment="@_order.Payment"
                     OnBack="@GoBackToShipping"
                     OnPlaceOrder="@HandlePlaceOrder" />
    }
</div>

@code {
    private enum Step { Shipping, Payment }

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private Step _step = Step.Shipping;

    private void HandleShippingComplete()
    {
        _step = Step.Payment;
    }

    private void GoBackToShipping()
    {
        _step = Step.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<h3>Shipping Information</h3>

<div class="form-group">
    <label>Name</label>
    <input @bind="Shipping.Name" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>Address</label>
    <input @bind="Shipping.Address" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>City</label>
    <input @bind="Shipping.City" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>Zip Code</label>
    <input @bind="Shipping.ZipCode" disabled="@_isValidating" />
</div>

@if (!string.IsNullOrEmpty(_validationError))
{
    <div class="validation-error">@_validationError</div>
}

<button disabled="@_isValidating" @onclick="ValidateAndProceed">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        <span>Validating…</span>
    }
    else
    {
        <span>Next</span>
    }
</button>

@code {
    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _validationError;

    private async Task ValidateAndProceed()
    {
        // Cancel any in-flight validation (e.g. user went back and changed fields).
        CancelPendingValidation();

        _validationError = null;
        _isValidating = true;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, cts.Token);

            // If this token was cancelled while awaiting, another call has
            // superseded us — bail out silently.
            cts.Token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check your details.";
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when the user navigates away or retries — nothing to do.
        }
        finally
        {
            // Only clear the loading state if *this* call is still the active one.
            if (_cts == cts)
            {
                _isValidating = false;
            }
        }
    }

    private void CancelPendingValidation()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

